import{_ as e,o as s,c as n,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"最小实践","description":"","frontmatter":{"title":"最小实践"},"headers":[],"relativePath":"ts-ai/foundations/langchain-bridge/index.md","filePath":"ts-ai/foundations/langchain-bridge/index.md","lastUpdated":1786083160000}'),i={name:"ts-ai/foundations/langchain-bridge/index.md"};function p(l,a,o,d,r,c){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="最小实践" tabindex="-1">最小实践 <a class="header-anchor" href="#最小实践" aria-label="Permalink to &quot;最小实践&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本组把前面的模型概念落实为四条可运行、可检查、可测试的 LangChain.js 调用链。示例沿用“前置与启动”中创建的 <code>ts-ai-starter</code>，使用环境变量选择模型，不把会快速变化的模型名写死在源码中。</p><p>示例 API 按 2026-08-08 的 <code>langchain@1.5.5</code>、<code>@langchain/core@1.2.5</code>、<code>@langchain/openai@1.5.6</code> 和 <code>zod@4.4.3</code> 核验。安装时以项目 lockfile 为准；版本变化后重新运行本组示例和契约测试。</p><h2 id="实践顺序" tabindex="-1">实践顺序 <a class="header-anchor" href="#实践顺序" aria-label="Permalink to &quot;实践顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>新增能力</th><th>可验证产物</th></tr></thead><tbody><tr><td><a href="/ts-ai/foundations/langchain-bridge/first-chatopenai-invoke">第一次 <code>ChatOpenAI.invoke()</code></a></td><td>初始化模型、发送消息、读取 <code>AIMessage</code> 和错误</td><td>一次真实文本调用及用量记录</td></tr><tr><td><a href="/ts-ai/foundations/langchain-bridge/prompt-template-messages"><code>PromptTemplate</code> 与 Message</a></td><td>渲染字符串 Prompt、聊天消息和历史占位</td><td>调用前可检查的最终 Message 数组</td></tr><tr><td><a href="/ts-ai/foundations/langchain-bridge/zod-structured-output">使用 Zod 获取结构化输出</a></td><td><code>withStructuredOutput()</code>、Zod 和业务规则</td><td>类型化工单草稿与失败处理</td></tr><tr><td><a href="/ts-ai/foundations/langchain-bridge/model-call-tests">模型调用的 Fake、Mock 与错误测试</a></td><td><code>fakeModel()</code>、Vitest、错误与调用记录</td><td>不访问网络的确定性测试套件</td></tr></tbody></table><h2 id="最小-api-链路" tabindex="-1">最小 API 链路 <a class="header-anchor" href="#最小-api-链路" aria-label="Permalink to &quot;最小 API 链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ChatPromptTemplate.fromMessages(...)</span></span>
<span class="line"><span>  .pipe(new ChatOpenAI(...).withStructuredOutput(schema, options))</span></span>
<span class="line"><span>  .invoke(values, runnableConfig)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这条链路中有三类不同契约：模型构造器保存长期模型配置，<code>invoke()</code> 的第二个参数保存单次运行与追踪配置，Zod Schema 定义运行时输出边界。不要把采样参数、业务输入和追踪元数据塞进同一个对象。</p><h2 id="示例项目约定" tabindex="-1">示例项目约定 <a class="header-anchor" href="#示例项目约定" aria-label="Permalink to &quot;示例项目约定&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├─ config/env.ts</span></span>
<span class="line"><span>├─ model/create-chat-model.ts</span></span>
<span class="line"><span>├─ prompts/support-prompt.ts</span></span>
<span class="line"><span>├─ services/support-service.ts</span></span>
<span class="line"><span>└─ examples/</span></span>
<span class="line"><span>   ├─ first-chat.ts</span></span>
<span class="line"><span>   ├─ prompt-messages.ts</span></span>
<span class="line"><span>   └─ structured-ticket.ts</span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>└─ support-service.test.ts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ul><li>真实模型只在显式运行 <code>src/examples/*</code> 时调用；</li><li>单元测试使用 <code>fakeModel()</code>，不需要 API Key，不产生模型费用；</li><li>所有模型结果在进入业务代码前保留 Message 或 Schema 边界；</li><li>输出是概率生成结果，文中的示例文本不是固定断言。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>完成四篇后，应能回答并用代码证明：</p><ol><li><code>ChatOpenAI</code> 构造器配置与 <code>invoke()</code> 运行配置有什么区别；</li><li><code>invoke()</code> 为什么返回 <code>AIMessage</code> 而不是字符串；</li><li>Prompt 模板渲染后实际发送了哪些角色和消息；</li><li>Zod 结构通过后为什么还要业务校验；</li><li>如何在没有网络、没有密钥的测试中固定模型响应并注入错误。</li></ol>`,15)])])}const b=e(i,[["render",p]]);export{u as __pageData,b as default};
